package worker

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

type ServiceCredential struct {
	ServiceID string
	Secret    []byte
	ExpiresAt time.Time
	revoked   bool
}

type CredentialStore struct {
	mu    sync.RWMutex
	creds map[string]*ServiceCredential
}

func NewCredentialStore() *CredentialStore {
	cs := &CredentialStore{
		creds: make(map[string]*ServiceCredential),
	}
	return cs
}

func (cs *CredentialStore) Register(serviceID string, secret []byte, ttl time.Duration) {
	cred := &ServiceCredential{}
	cred.ServiceID = serviceID
	cred.Secret = make([]byte, len(secret))
	copy(cred.Secret, secret)
	cred.ExpiresAt = time.Now().Add(ttl)
	cred.revoked = false

	cs.mu.Lock()
	cs.creds[serviceID] = cred
	cs.mu.Unlock()
}

func (cs *CredentialStore) Revoke(serviceID string) {
	cs.mu.Lock()
	if cred, ok := cs.creds[serviceID]; ok {
		cred.revoked = true
		delete(cs.creds, serviceID)
	}
	cs.mu.Unlock()
}

func (cs *CredentialStore) Lookup(serviceID string) (*ServiceCredential, bool) {
	cs.mu.RLock()
	cred, ok := cs.creds[serviceID]
	cs.mu.RUnlock()
	return cred, ok
}

type Job struct {
	ID        string
	Payload   []byte
	ServiceID string
	Signature string
}

type Worker struct {
	store    *CredentialStore
	jobQueue chan *Job
	results  chan string
	ctx      context.Context
	cancel   context.CancelFunc
}

func NewWorker(store *CredentialStore, queueSize int) *Worker {
	ctx, cancel := context.WithCancel(context.Background())
	return &Worker{
		store:    store,
		jobQueue: make(chan *Job, queueSize),
		results:  make(chan string, queueSize),
		ctx:      ctx,
		cancel:   cancel,
	}
}

func (w *Worker) Submit(job *Job) {
	w.jobQueue <- job
}

func (w *Worker) Start(numWorkers int) {
	for i := 0; i < numWorkers; i++ {
		go w.processLoop()
	}
}

func (w *Worker) processLoop() {
	for {
		select {
		case <-w.ctx.Done():
			return
		case job := <-w.jobQueue:
			w.handleJob(job)
		}
	}
}

func (w *Worker) handleJob(job *Job) {
	cred, ok := w.store.Lookup(job.ServiceID)
	if !ok {
		w.results <- fmt.Sprintf("job %s: unknown service %s", job.ID, job.ServiceID)
		return
	}

	// Simulate async processing delay - credential may be revoked during
	// this window, but the struct remains valid and its revoked flag is set
	time.Sleep(50 * time.Millisecond)

	// Even if revoked concurrently, the struct is not reused so the
	// revoked flag reliably reflects this credential's state
	if cred.revoked {
		w.results <- fmt.Sprintf("job %s: credential revoked", job.ID)
		return
	}

	if time.Now().After(cred.ExpiresAt) {
		w.results <- fmt.Sprintf("job %s: credential expired", job.ID)
		return
	}

	if !w.verifySignature(job.Payload, cred.Secret, job.Signature) {
		w.results <- fmt.Sprintf("job %s: invalid signature", job.ID)
		return
	}

	w.results <- fmt.Sprintf("job %s: processed successfully", job.ID)
}

func (w *Worker) verifySignature(payload, secret []byte, signature string) bool {
	mac := hmac.New(sha256.New, secret)
	mac.Write(payload)
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

func (w *Worker) Stop() {
	w.cancel()
}

// RunGarbageCollector periodically revokes expired credentials
func RunGarbageCollector(store *CredentialStore, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for range ticker.C {
		now := time.Now()
		store.mu.RLock()
		var expired []string
		for id, cred := range store.creds {
			if now.After(cred.ExpiresAt) {
				expired = append(expired, id)
			}
		}
		store.mu.RUnlock()
		for _, id := range expired {
			store.Revoke(id)
		}
	}
}
